 * Find the sequence of (baseIndex, sideIndex) pairs of matched, identical
 * lines between `base` and `side`, following the longest-common-subsequence
 * with earliest-match tie-breaking.
 */
function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // dp[i][j] holds the LCS length of base[i:] and side[j:], stored as a flat
  // (n+1) x (m+1) array of suffix lengths so the forward walk below can
  // compare "remaining subsequence" lengths without recomputation.
  const width = m + 1
  const dp = new Int32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      const here = i * width + j
      if (base[i] === side[j]) {
        dp[here] = dp[(i + 1) * width + (j + 1)] + 1
      } else {
        const advanceBase = dp[(i + 1) * width + j]
        const advanceSide = dp[i * width + (j + 1)]
        dp[here] = advanceBase >= advanceSide ? advanceBase : advanceSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
