 * Group changes into regions: consecutive changes are absorbed into the same
 * region while a change starts at or before the region's current end.
 */
function buildRegions(changes) {
  const regions = []
  let i = 0
  while (i < changes.length) {
    let start = changes[i].baseStart
    let end = changes[i].baseEnd
    const group = [changes[i]]
    i++
    while (i < changes.length && changes[i].baseStart <= end) {
      group.push(changes[i])
      if (changes[i].baseEnd > end) end = changes[i].baseEnd
      i++
    }
    regions.push({ baseStart: start, baseEnd: end, changes: group })
  }
  return regions
