  if (sideChanges.length === 0) return base.slice(regionStart, regionEnd)
  const result = base.slice(regionStart, sideChanges[0].baseStart)
  let cursor = sideChanges[0].baseStart
  for (const change of sideChanges) {
    result.push(...base.slice(cursor, change.baseStart))
    result.push(...change.lines)
    cursor = change.baseEnd
  }
  result.push(...base.slice(cursor, regionEnd))
  return result
