    type = mineChanges.length > 0 && theirsChanges.length > 0 ? 'both' : mineChanges.length > 0 ? 'mine' : 'theirs'
  } else if (arraysEqual(mineLines, baseLines)) {
    type = 'theirs'
  } else if (arraysEqual(theirsLines, baseLines)) {
    type = 'mine'
  } else {
    type = 'conflict'
