/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { mergeBlocks } from './merge.js'
import { renderMerge, renderRegions } from './format.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function splitDocuments(lines) {
  const docs = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      docs.push([])
    } else {
      docs[docs.length - 1].push(line)
    }
  }
  return docs
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) {
    fail('usage: cli.js merge|merge2|regions')
  }

  const input = readFileSync(0, 'utf8')
  const lines = splitLines(input)
  const docs = splitDocuments(lines)
  if (docs.length !== 3) {
    fail('expected three parts separated by %%%')
  }

  const [mine, base, theirs] = docs
  const blocks = mergeBlocks(mine, base, theirs)

  const { text, hadConflict } =
    mode === 'regions' ? renderRegions(blocks) : renderMerge(blocks, { includeBase: mode === 'merge' })

  process.stdout.write(text)
  process.exit(hadConflict ? 1 : 0)
}

main()
"}

